def transform(grid):
    R,C=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(R):
        for c in range(C):
            if grid[r][c]!=2 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=y+dy,x+dx
                    if 0<=q[0]<R and 0<=q[1]<C and grid[q[0]][q[1]]==2 and q not in seen:
                        seen.add(q); stack.append(q)
            if len(cells)==4:
                ys=[y for y,x in cells]; xs=[x for y,x in cells]
                rowcounts={y:sum(yy==y for yy,x in cells) for y in set(ys)}
                bar=next((y for y,n in rowcounts.items() if n==3),None)
                stem=next((y for y,n in rowcounts.items() if n==1),None)
                if bar is not None and stem is not None:
                    objs.append((min(ys),min(xs), 3 if stem>bar else 1))
    out=[[0]*6 for _ in range(3)]
    # Each orientation has a 3x3 panel; positions reflect coarse vertical bands.
    for y,x,v in objs:
        rr=0 if y < R/3 else (1 if y < 2*R/3 else 2)
        col=0 if v==3 else 3
        out[rr][col]=v
    return out
